import ast
import hashlib
import json
import subprocess
from collections import Counter
from pathlib import Path

ROOT = Path('local-artifacts/marin-native-jax-fp8-raw-microbatch-final')
BASE = '7bcab4c6385967bad9935807033d2b30b61da9aa'
CONSTANTS = {
    'lib/levanter/src/levanter/models/llama_native.py': {
        '_HF_TOKEN_EMBEDDING_WEIGHT_KEY': 'model.embed_tokens.weight',
        '_HF_FINAL_NORM_PREFIX': 'model.norm',
    },
    'lib/levanter/src/levanter/models/llama_native_lm.py': {
        '_LEVANTER_MODEL_METADATA_KEY': 'levanter_model',
    },
}


class ExpandConstants(ast.NodeTransformer):
    def __init__(self, values):
        self.values = values
        self.references = Counter()

    def visit_Name(self, node):
        if node.id not in self.values:
            return node
        assert isinstance(node.ctx, ast.Load), node.id
        self.references[node.id] += 1
        return ast.copy_location(ast.Constant(value=self.values[node.id]), node)


def digest(value):
    return hashlib.sha256(value).hexdigest()


def main():
    records = {}
    for file, values in CONSTANTS.items():
        original_bytes = subprocess.check_output(['git', 'show', BASE + ':' + file], cwd=ROOT)
        candidate_bytes = (ROOT / file).read_bytes()
        original = ast.parse(original_bytes)
        candidate = ast.parse(candidate_bytes)
        definitions = []
        retained = []
        for node in candidate.body:
            if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                name = node.targets[0].id
                if name in values:
                    assert isinstance(node.value, ast.Constant) and node.value.value == values[name]
                    definitions.append(name)
                    continue
            retained.append(node)
        assert sorted(definitions) == sorted(values)
        candidate.body = retained
        expander = ExpandConstants(values)
        expanded = expander.visit(candidate)
        original_dump = ast.dump(original, include_attributes=False)
        expanded_dump = ast.dump(expanded, include_attributes=False)
        assert original_dump == expanded_dump, file
        old_literals = Counter(node.value for node in ast.walk(original) if isinstance(node, ast.Constant) and isinstance(node.value, str))
        new_literals = Counter(node.value for node in ast.walk(ast.parse(candidate_bytes)) if isinstance(node, ast.Constant) and isinstance(node.value, str))
        for name, value in values.items():
            assert old_literals[value] == expander.references[name]
            assert new_literals[value] == 1
        records[file] = {
            'base': BASE,
            'original_blob': subprocess.check_output(['git', 'rev-parse', BASE + ':' + file], cwd=ROOT, text=True).strip(),
            'original_sha256': digest(original_bytes),
            'candidate_sha256': digest(candidate_bytes),
            'literal_values': values,
            'reference_counts': dict(expander.references),
            'all_exact_literals_hoisted_only_once': True,
            'expanded_AST_equals_original': True,
            'original_AST_sha256': digest(original_dump.encode()),
            'expanded_AST_sha256': digest(expanded_dump.encode()),
        }
    result = {
        'method': 'Remove only three exact module-level literal definitions; expand only their load references to original byte-identical string values; compare full AST excluding location attributes.',
        'project_imports_or_tests': False,
        'files': records,
    }
    path = Path('local-artifacts/native-jax-fp8-raw-microbatch-catalog-response-ast-proof.json')
    path.write_text(json.dumps(result, indent=2) + '\n')
    print(path, digest(path.read_bytes()))


if __name__ == '__main__':
    main()
